const upsertDepartmentBySource = `-- name: UpsertDepartmentBySource :one
INSERT INTO departments (entity_id, organization_id, name, parent_id, source_id, external_department_id)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (entity_id, source_id, external_department_id) WHERE source_id IS NOT NULL AND external_department_id IS NOT NULL
DO UPDATE SET
    name = EXCLUDED.name,
    parent_id = EXCLUDED.parent_id,
    organization_id = EXCLUDED.organization_id,
    updated_at = now()
RETURNING id, entity_id, organization_id, name, parent_id, source_id, external_department_id, created_at, updated_at
`

type UpsertDepartmentBySourceParams struct {
	EntityID             string      `json:"entity_id"`
	OrganizationID       string      `json:"organization_id"`
	Name                 string      `json:"name"`
	ParentID             pgtype.Text `json:"parent_id"`
	SourceID             pgtype.Text `json:"source_id"`
	ExternalDepartmentID pgtype.Text `json:"external_department_id"`
}

func (q *Queries) UpsertDepartmentBySource(ctx context.Context, arg UpsertDepartmentBySourceParams) (Department, error) {
	row := q.db.QueryRow(ctx, upsertDepartmentBySource,
		arg.EntityID,
		arg.OrganizationID,
		arg.Name,
		arg.ParentID,
		arg.SourceID,
		arg.ExternalDepartmentID,
	)
	var i Department
	err := row.Scan(
		&i.ID,
		&i.EntityID,
		&i.OrganizationID,
		&i.Name,
		&i.ParentID,
		&i.SourceID,
		&i.ExternalDepartmentID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
